<script setup lang="ts">
import {ref,reactive,onMounted} from 'vue'
import {api,ApiError} from '../../api/leaseguard'
import {useAuthStore} from '../../stores/auth'
import {validMoney} from '../../api/contracts'
import {repairLabels} from '../../types/leaseguard'
import type {WorkTicket,Technician,Fault,Id} from '../../types/leaseguard'
import Timeline from './Timeline.vue'
const auth=useAuthStore(),rows=ref<WorkTicket[]>([]),techs=ref<Technician[]>([]),faults=ref<Fault[]>([]),selected=ref<WorkTicket|null>(null),page=ref(1),total=ref(0),filter=ref<number|''>(''),busy=ref(false),loading=ref(false),error=ref(''),message=ref(''),assignee=ref(''),cost=ref('0.00'),remark=ref('')
const account=reactive({username:'',password:''})
async function load(){loading.value=true;try{const r=await api.tickets(page.value,filter.value);rows.value=r.data.records;total.value=r.data.total;if(selected.value)selected.value=(await api.ticket(selected.value.id)).data;if(auth.isAdmin){techs.value=(await api.technicians()).data;faults.value=(await api.faults(true)).data.records}}catch(e){selected.value=null;error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function act(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();await load();message.value='操作已保存'}catch(e){error.value=e instanceof Error?e.message:'操作失败';if(e instanceof ApiError&&e.status===409)await load()}finally{busy.value=false}}
async function detail(id:Id){await act(async()=>{selected.value=(await api.ticket(id)).data;assignee.value=selected.value.assigneeId||''})}
async function assign(){if(!selected.value||!assignee.value)return;const t=selected.value;await act(()=>api.assign(t.id,assignee.value,t.version))}
async function complete(){if(!validMoney(cost.value)){error.value='费用须为非负金额，最多两位小数';return}if(selected.value)await act(()=>api.complete(selected.value!.id,cost.value))}
async function createTech(){await act(async()=>{await api.createTechnician(account);account.password='';account.username=''})}
onMounted(load)
</script>
<template><section v-loading="loading" class="lease-panel"><h1>{{auth.isAdmin?'故障审核与维修派工':'我的维修工作台'}}</h1><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/><el-button @click="load" :disabled="busy">刷新</el-button><label>维修状态筛选 <select v-model="filter" @change="page=1;load()"><option value="">全部</option><option v-for="(label,key) in repairLabels" :key="key" :value="Number(key)">{{label}}</option></select></label>
<template v-if="auth.isAdmin"><details><summary>建立技师账号</summary><form @submit.prevent="createTech"><label>技师用户名 <input v-model="account.username" pattern="[A-Za-z0-9_]{4,20}" required/></label><label>技师初始密码 <input v-model="account.password" type="password" minlength="12" maxlength="64" autocomplete="new-password" required/></label><el-button native-type="submit" :disabled="busy">建立技师</el-button></form></details><h2>故障审核</h2><el-table :data="faults" row-key="id"><el-table-column prop="reportNo" label="故障编号"/><el-table-column prop="faultDescription" label="描述"/><el-table-column label="审核状态"><template #default="{row}">{{['待审核','已确认','已驳回'][row.auditStatus]}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><template v-if="row.auditStatus===0"><el-button :disabled="busy" @click="act(()=>api.audit(row.id,true))">确认故障</el-button><el-button :disabled="busy" @click="act(()=>api.audit(row.id,false))">驳回故障</el-button></template></template></el-table-column></el-table></template>
<h2>维修工单</h2><p>仅被分配技师可以开始和提交；提交完成仍需管理员独立验收。</p><el-empty v-if="!loading&&!error&&!rows.length" description="暂无授权工单"/><el-table :data="rows" row-key="id"><el-table-column prop="ticketNo" label="工单编号"/><el-table-column prop="droneModel" label="设备"/><el-table-column label="状态"><template #default="{row}">{{repairLabels[(row as WorkTicket).status]}}</template></el-table-column><el-table-column label="负责人"><template #default="{row}">{{row.assigneeId?row.assigneeName:'未分配（历史姓名不授权）'}}</template></el-table-column><el-table-column prop="acceptedAt" label="验收时间"/><el-table-column label="操作"><template #default="{row}"><el-button :disabled="busy" @click="detail(row.id)">工单详情</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="load"/>
<el-card v-if="selected" class="detail" data-testid="repair-detail"><h2>{{selected.ticketNo}}</h2><p>维修状态：<strong>{{repairLabels[selected.status]}}</strong> · 版本 {{selected.version}}</p><p>型号 {{selected.droneModel}} · {{selected.faultType}} · {{selected.description}}</p><p>负责人 {{selected.assigneeId?selected.assigneeName:'未分配'}} · 派工时间 {{selected.assignedAt||'无'}}</p>
<template v-if="auth.isAdmin"><template v-if="selected.status===0"><label for="repair-assignee">分配技师</label><select id="repair-assignee" v-model="assignee" required><option value="" disabled>选择启用的技师</option><option v-for="t in techs" :key="t.id" :value="t.id">{{t.username}}</option></select><el-button :disabled="busy||!assignee" @click="assign">确认派工</el-button></template><template v-if="selected.status===4"><label>独立验收意见 <input v-model="remark" maxlength="500"/></label><el-button :disabled="busy" @click="act(()=>api.accept(selected!.id,remark))">验收维修</el-button></template></template>
<template v-if="auth.isTechnician"><el-button v-if="selected.status===0" :disabled="busy" @click="act(()=>api.start(selected!.id))">开始维修</el-button><template v-if="selected.status===1"><label>实际维修费用 <input v-model="cost" inputmode="decimal"/></label><el-button :disabled="busy||!validMoney(cost)" @click="complete">提交维修完成</el-button></template><p v-if="selected.status===4">等待管理员独立验收，设备尚未恢复可租。</p></template><p v-if="selected.acceptedAt">验收时间 {{selected.acceptedAt}}</p><Timeline :key="selected.id+'-'+selected.version" kind="tickets" :resource-id="selected.id"/></el-card></section></template>
<style scoped>.lease-panel{padding:20px}label{display:inline-block;margin:10px}input,select{padding:8px}h2,details{margin:18px 0}.detail{margin-top:20px}</style>
